namespace sv_59a4a0c5c27548428a0b34bd92678e5e.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@namespace sv_59a4a0c5c27548428a0b34bd92678e5e.Components.JobApplication

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var stepIndex = i;
            var css = stepIndex == CurrentStep ? "step active"
                    : stepIndex < CurrentStep ? "step completed"
                    : "step future";

            <li class="@css">
                @if (stepIndex < CurrentStep)
                {
                    <button class="step-button" @onclick="() => OnStepClicked.InvokeAsync(stepIndex)">
                        <span class="step-icon">&#10003;</span>
                        <span class="step-label">@StepNames[stepIndex]</span>
                    </button>
                }
                else
                {
                    <span class="step-content">
                        <span class="step-icon">@(stepIndex + 1)</span>
                        <span class="step-label">@StepNames[stepIndex]</span>
                    </span>
                }
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnStepClicked { get; set; }

    private static readonly List<string> StepNames = new()
    {
        "Personal Info",
        "Work History",
        "References",
        "Cover Letter",
        "Review & Submit"
    };
}

@namespace sv_59a4a0c5c27548428a0b34bd92678e5e.Components.JobApplication

<div class="step-form">
    <h2>Personal Information</h2>

    <div class="form-group">
        <label for="fullName">Full Name *</label>
        <input id="fullName" type="text" @bind="FullName" @bind:event="oninput" class="form-control" />
    </div>

    <div class="form-group">
        <label for="email">Email *</label>
        <input id="email" type="email" @bind="Email" @bind:event="oninput" class="form-control" />
    </div>

    <div class="form-group">
        <label for="phone">Phone *</label>
        <input id="phone" type="tel" @bind="Phone" @bind:event="oninput" class="form-control" />
    </div>

    <div class="form-group">
        <label for="address">Address *</label>
        <input id="address" type="text" @bind="Address" @bind:event="oninput" class="form-control" />
    </div>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message">@ErrorMessage</div>
    }

    <div class="step-actions">
        <button class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @(IsValidating ? "Validating..." : "Next")
        </button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<PersonalInfoResult> OnNext { get; set; }

    private string? ErrorMessage;
    private bool IsValidating;

    public record PersonalInfoResult(string FullName, string Email, string Phone, string Address);

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(FullName))
        {
            ErrorMessage = "Full name is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Email))
        {
            ErrorMessage = "Email is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Phone))
        {
            ErrorMessage = "Phone is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Address))
        {
            ErrorMessage = "Address is required.";
            return;
        }

        IsValidating = true;
        ErrorMessage = null;
        StateHasChanged();

        var isEmailValid = await ValidateEmail.InvokeAsync(Email);
        IsValidating = false;

        if (!isEmailValid)
        {
            ErrorMessage = "The email address is not valid.";
            return;
        }

        await OnNext.InvokeAsync(new PersonalInfoResult(FullName.Trim(), Email.Trim(), Phone.Trim(), Address.Trim()));
    }

    [Parameter, EditorRequired] public Func<string, Task<bool>> ValidateEmail { get; set; } = default!;
}

@namespace sv_59a4a0c5c27548428a0b34bd92678e5e.Components.JobApplication

<fieldset class="work-entry">
    <legend>Position @(Index + 1)</legend>

    @if (CanRemove)
    {
        <button type="button" class="btn btn-danger btn-sm remove-btn" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
    }

    <div class="form-group">
        <label>Company *</label>
        <input type="text" @bind="Entry.Company" @bind:event="oninput" class="form-control" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" @bind="Entry.Title" @bind:event="oninput" class="form-control" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" @bind="Entry.StartDate" class="form-control" />
        </div>

        <div class="form-group">
            @if (!Entry.IsCurrent)
            {
                <label>End Date</label>
                <input type="date" @bind="Entry.EndDate" class="form-control" />
            }
        </div>
    </div>

    <div class="form-group form-check">
        <input type="checkbox" id="current-@Index" @bind="Entry.IsCurrent" />
        <label for="current-@Index">I currently work here</label>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea @bind="Entry.Description" @bind:event="oninput" class="form-control" rows="3"></textarea>
    </div>
</fieldset>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }
}

@namespace sv_59a4a0c5c27548428a0b34bd92678e5e.Components.JobApplication

<div class="step-form">
    <h2>Work History</h2>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryEditor Entry="Entries[index]" Index="index"
                         CanRemove="Entries.Count > 1"
                         OnRemove="() => RemoveEntry(index)" />
    }

    <button type="button" class="btn btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message">@ErrorMessage</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<WorkEntryEditor.WorkEntryModel>? InitialEntries { get; set; }
    [Parameter, EditorRequired] public EventCallback<List<WorkEntryEditor.WorkEntryModel>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private List<WorkEntryEditor.WorkEntryModel> Entries = new();
    private string? ErrorMessage;

    protected override void OnInitialized()
    {
        if (InitialEntries is { Count: > 0 })
        {
            Entries = InitialEntries;
        }
        else
        {
            Entries.Add(new WorkEntryEditor.WorkEntryModel());
        }
    }

    private void AddEntry() => Entries.Add(new WorkEntryEditor.WorkEntryModel());

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
            Entries.RemoveAt(index);
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;
        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                ErrorMessage = "Each position requires at least a company name and job title.";
                return;
            }
        }
        await OnNext.InvokeAsync(Entries);
    }
}

@namespace sv_59a4a0c5c27548428a0b34bd92678e5e.Components.JobApplication

<fieldset class="reference-entry">
    <legend>Reference @(Index + 1)</legend>

    @if (CanRemove)
    {
        <button type="button" class="btn btn-danger btn-sm remove-btn" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
    }

    <div class="form-group">
        <label>Name *</label>
        <input type="text" @bind="Entry.Name" @bind:event="oninput" class="form-control" />
    </div>

    <div class="form-group">
        <label>Relationship *</label>
        <input type="text" @bind="Entry.Relationship" @bind:event="oninput" class="form-control" />
    </div>

    <div class="form-group">
        <label>Email *</label>
        <input type="email" @bind="Entry.Email" @bind:event="oninput" class="form-control" />
    </div>

    <div class="form-group">
        <label>Phone *</label>
        <input type="tel" @bind="Entry.Phone" @bind:event="oninput" class="form-control" />
    </div>
</fieldset>

@code {
    [Parameter, EditorRequired] public ReferenceModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

@namespace sv_59a4a0c5c27548428a0b34bd92678e5e.Components.JobApplication

<div class="step-form">
    <h2>References</h2>
    <p class="hint">Please provide 2–3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <ReferenceEditor Entry="References[index]" Index="index"
                         CanRemove="References.Count > 2"
                         OnRemove="() => RemoveReference(index)" />
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message">@ErrorMessage</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<ReferenceEditor.ReferenceModel>? InitialReferences { get; set; }
    [Parameter, EditorRequired] public EventCallback<List<ReferenceEditor.ReferenceModel>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private List<ReferenceEditor.ReferenceModel> References = new();
    private string? ErrorMessage;

    protected override void OnInitialized()
    {
        if (InitialReferences is { Count: > 0 })
        {
            References = InitialReferences;
        }
        else
        {
            References.Add(new ReferenceEditor.ReferenceModel());
            References.Add(new ReferenceEditor.ReferenceModel());
        }
    }

    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(new ReferenceEditor.ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
            References.RemoveAt(index);
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;
        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                ErrorMessage = "All reference fields are required.";
                return;
            }
        }
        await OnNext.InvokeAsync(References);
    }
}

@namespace sv_59a4a0c5c27548428a0b34bd92678e5e.Components.JobApplication

<div class="step-form">
    <h2>Cover Letter</h2>

    <div class="form-group">
        <label for="coverLetter">Write your cover letter</label>
        <textarea id="coverLetter" @bind="CoverLetter" @bind:event="oninput"
                  class="form-control cover-letter-textarea" rows="12" maxlength="2000"></textarea>
        <div class="char-count">@CoverLetter.Length / 2000 characters</div>
    </div>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message">@ErrorMessage</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<string> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private async Task HandleNext()
    {
        if (string.IsNullOrWhiteSpace(CoverLetter))
        {
            ErrorMessage = "A cover letter is required.";
            return;
        }
        await OnNext.InvokeAsync(CoverLetter);
    }
}

@namespace sv_59a4a0c5c27548428a0b34bd92678e5e.Components.JobApplication

<div class="step-form review-step">
    <h2>Review & Submit</h2>

    @if (IsSubmitted)
    {
        <div class="confirmation">
            <h3>&#10003; Application Submitted!</h3>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
            <p>Thank you for applying. We will be in touch.</p>
        </div>
    }
    else
    {
        <section class="review-section">
            <div class="review-header">
                <h3>Personal Information</h3>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
            </div>
            <dl>
                <dt>Name</dt><dd>@Personal.FullName</dd>
                <dt>Email</dt><dd>@Personal.Email</dd>
                <dt>Phone</dt><dd>@Personal.Phone</dd>
                <dt>Address</dt><dd>@Personal.Address</dd>
            </dl>
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>Work History</h3>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-work-entry">
                    <strong>@entry.Title</strong> at @entry.Company
                    <br />
                    <span class="dates">@entry.StartDate.ToString("MMM yyyy") – @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))</span>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p>@entry.Description</p>
                    }
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>References</h3>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var r in References)
            {
                <div class="review-reference">
                    <strong>@r.Name</strong> (@r.Relationship)
                    <br />@r.Email | @r.Phone
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>Cover Letter</h3>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
            </div>
            <p class="cover-letter-preview">@CoverLetter</p>
        </section>

        @if (!string.IsNullOrEmpty(ErrorMessage))
        {
            <div class="error-message">@ErrorMessage</div>
        }

        <div class="step-actions">
            <button class="btn btn-outline" @onclick="OnBack">Back</button>
            <button class="btn btn-primary btn-submit" @onclick="HandleSubmit" disabled="@IsSubmitting">
                @(IsSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoStep.PersonalInfoResult Personal { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkEntryEditor.WorkEntryModel> WorkEntries { get; set; } = default!;
    [Parameter, EditorRequired] public List<ReferenceEditor.ReferenceModel> References { get; set; } = default!;
    [Parameter, EditorRequired] public string CoverLetter { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<int> OnEditStep { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter, EditorRequired] public Func<Task<int>> OnSubmit { get; set; } = default!;

    private bool IsSubmitting;
    private bool IsSubmitted;
    private int ApplicationId;
    private string? ErrorMessage;

    private async Task HandleSubmit()
    {
        IsSubmitting = true;
        ErrorMessage = null;
        StateHasChanged();

        try
        {
            ApplicationId = await OnSubmit();
            IsSubmitted = true;
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            IsSubmitting = false;
        }
    }
}

namespace sv_59a4a0c5c27548428a0b34bd92678e5e.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@namespace sv_59a4a0c5c27548428a0b34bd92678e5e.Components.JobApplication

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var stepIndex = i;
            var css = stepIndex == CurrentStep ? "step active"
